<div class="row g-3"><div class="col-lg-6"><div class="card"><div class="card-body small">
  <h2 class="h6"><?= e($t['number']) ?> <?= App\Core\View::partial('pay::_status', ['s' => $t['status'], 'test' => (int) $t['is_test']]) ?></h2>
  <table class="table table-sm mb-2">
  <?php foreach ([['Montant', money($t['amount']) . ' ' . $t['currency']], ['Débité chez le prestataire', $t['provider_amount'] !== null ? $t['provider_amount'] . ' ' . $t['provider_currency'] . ($t['exchange_rate'] ? ' (' . t('taux') . ' ' . rtrim(rtrim((string) $t['exchange_rate'], '0'), '.') . ')' : '') : '—'],
      ['Frais', $t['fees'] !== null ? money($t['fees']) : '—'], ['Remboursé', money($t['refunded_amount'])], ['Moyen', $t['method'] . ' → ' . method_label($t['sale_method'])], ['Prestataire / terminal', $t['connector'] ?? $t['terminal'] ?? ''],
      ['Vente', $t['sale_number'] ?? '—'], ['Client', $t['customer'] ?? '—'], ['Payeur', $t['payer_hint'] ?? '—'], ['Caisse / caissier', ($t['register'] ?? '') . ' · ' . ($t['cashier'] ?? '')],
      ['Référence du prestataire', $t['provider_reference'] ?? '—'], ['N° d\'autorisation', $t['authorization_code'] ?? '—'], ['Confirmé par', $t['verified_by'] ? ['api' => t('vérification serveur à serveur'), 'webhook' => t('notification signée'), 'reconciliation' => t('rapprochement'), 'terminal' => t('terminal')][$t['verified_by']] : '—'],
      ['Créée', fdate($t['created_at'])], ['Expiration', fdate($t['expires_at'])], ['Réussie le', fdate($t['succeeded_at']) ?: '—'], ['Message', $t['message'] ?? '']] as [$k, $v]): ?>
    <tr><th class="w-50"><?= e(t($k)) ?></th><td class="text-break"><?= e((string) $v) ?></td></tr><?php endforeach; ?>
