  <?php if ($t['redirect_url'] && in_array($t['status'], ['pending', 'processing'], true)): ?><p><a href="<?= e($t['redirect_url']) ?>" target="_blank" rel="noopener noreferrer"><?= e(t('Page de paiement du prestataire')) ?></a></p><?php endif; ?>
  <div class="d-flex flex-wrap gap-2">
    <?php if (in_array($t['status'], ['pending', 'processing', 'to_verify'], true)): ?><form method="post" action="<?= e(url('/pay/transactions/' . $t['id'] . '/verifier')) ?>"><?= csrf_field() ?><button class="btn btn-sm btn-outline-primary"><i class="bi bi-arrow-repeat"></i> <?= e(t('Vérifier auprès du prestataire')) ?></button></form><?php endif; ?>
    <?php if ($canCancel && can('pay.refund') && (in_array($t['status'], ['pending', 'processing'], true) || ($t['status'] === 'succeeded' && !$t['sale_id'] && !(float) $t['refunded_amount']))): ?><form method="post" action="<?= e(url('/pay/transactions/' . $t['id'] . '/annuler')) ?>" data-confirm="<?= e(t('Demander l\'annulation au prestataire ?')) ?>"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger"><?= e(t('Annuler')) ?></button></form><?php endif; ?>
    <?php if ($t['sale_id']): ?><a class="btn btn-sm btn-outline-secondary" href="<?= e(url('/sales/' . $t['sale_id'])) ?>"><?= e(t('Voir la vente')) ?></a><?php endif; ?>
  </div>
</div></div>
<?php if (in_array($t['status'], ['succeeded', 'partially_refunded'], true)): ?><div class="card mt-3"><div class="card-header fw-semibold"><?= e(t('Remboursement')) ?></div><div class="card-body">
  <?php if (!$canRefund): ?><p class="small text-secondary mb-0"><?= e(t('Remboursement électronique non pris en charge par ce prestataire : remboursez par un autre moyen (Retours) — rien n\'est enregistré ici sans confirmation du prestataire.')) ?></p>
  <?php else: ?><form method="post" action="<?= e(url('/pay/transactions/' . $t['id'] . '/rembourser')) ?>" class="row g-2" data-confirm="<?= e(t('Transmettre ce remboursement au prestataire ?')) ?>"><?= csrf_field() ?><input type="hidden" name="request_key" value="<?= e(sprintf('%04x%04x-%04x-%04x-%04x-%04x%04x%04x', random_int(0, 0xffff), random_int(0, 0xffff), random_int(0, 0xffff), random_int(0, 0x0fff) | 0x4000, random_int(0, 0x3fff) | 0x8000, random_int(0, 0xffff), random_int(0, 0xffff), random_int(0, 0xffff))) ?>">
    <div class="col-md-4"><label class="form-label small mb-0"><?= e(t('Montant (max.)')) ?> <?= e(money($left)) ?></label><input name="amount" value="<?= e((string) $left) ?>" class="form-control form-control-sm" required></div>
    <div class="col-md-8"><label class="form-label small mb-0"><?= e(t('Justification (obligatoire)')) ?></label><input name="reason" minlength="5" maxlength="255" class="form-control form-control-sm" required></div>
    <?php if (!can('pay.refund')): ?><div class="col-md-6"><label class="form-label small mb-0"><?= e(t('Responsable')) ?></label><input name="sup_username" class="form-control form-control-sm" autocomplete="off" required></div>
    <div class="col-md-6"><label class="form-label small mb-0"><?= e(t('Mot de passe ou code du responsable')) ?></label><input type="password" name="sup_secret" class="form-control form-control-sm" autocomplete="new-password" required></div><?php endif; ?>
    <div class="col-12"><button class="btn btn-sm btn-warning"><i class="bi bi-arrow-counterclockwise"></i> <?= e(t('Rembourser via le prestataire')) ?></button></div></form><?php endif; ?>
</div></div><?php endif; ?>
<?php if ($refunds): ?><div class="card mt-3"><div class="card-header fw-semibold"><?= e(t('Historique des remboursements')) ?></div><ul class="list-group list-group-flush small"><?php foreach ($refunds as $f): ?><li class="list-group-item"><?= e($f['number']) ?> · <?= e(money($f['amount'])) ?> · <b><?= e($f['status']) ?></b> · <?= e($f['reason']) ?> · <?= e($f['requester'] ?? '') ?><?= $f['approver'] && $f['approver'] !== $f['requester'] ? ' (' . e(t('autorisé par')) . ' ' . e($f['approver']) . ')' : '' ?> · <?= e(fdate($f['created_at'])) ?> <code><?= e($f['provider_reference'] ?? '') ?></code></li><?php endforeach; ?></ul></div><?php endif; ?>
</div>
