<?php if ($logs): ?><div class="card"><div class="card-header fw-semibold"><?= e(t('Échanges avec le prestataire')) ?></div><ul class="list-group list-group-flush small"><?php foreach ($logs as $l): ?><li class="list-group-item"><a href="<?= e(url('/pay/journaux/' . $l['id'])) ?>"><?= e(fdate($l['created_at'])) ?></a> · <code><?= e($l['action']) ?></code> → <b><?= e($l['result_code']) ?></b> <?= $l['http_status'] ? 'HTTP ' . (int) $l['http_status'] : '' ?> <?= $l['duration_ms'] !== null ? (int) $l['duration_ms'] . ' ms' : '' ?> <span class="text-secondary"><?= e($l['message'] ?? '') ?></span></li><?php endforeach; ?></ul></div><?php endif; ?></div></div>
